# guess(num) is provided by the judge: -1 if the pick is lower, 1 if higher, 0 if num is the pick
class Solution:
    def guessNumber(self, n: int) -> int:
        lo, hi = 1, n
        while lo <= hi:
            mid = lo + (hi - lo) // 2
            res = guess(mid)                     # one API call per step
            if res == 0:
                return mid
            if res < 0:
                hi = mid - 1
            else:
                lo = mid + 1
        return -1
